import React, { useState } from 'react';
import { Card, Input, DatePicker, Button, Select } from 'antd';
import { useNormalFlightSearch } from './hooks/useNormalFlightSearch';
import NormalFlightAvailabilityCalendar from './NormalFlightAvailabilityCalendar';

const { RangePicker } = DatePicker;

const NormalRouteBuilder = () => {
  // State for form inputs
  const [path, setPath] = useState('');
  const [dateRange, setDateRange] = useState([]);
  const [sourcesExcluded, setSourcesExcluded] = useState([]);
  const [apiKey, setApiKey] = useState('');

  // Custom hook for flight search functionality
  const { flightData, currentRoute, isLoading, errors, handleSearch } = useNormalFlightSearch();

  // Handle form submission
  const onSearch = () => {
    handleSearch({
      path,
      dateRange,
      sourcesExcluded,
      apiKey
    });
  };

  // Get all available source codenames
  const getSourceCodenames = () => {
    return ['smiles', 'united', 'lifemiles', 'aeroplan'];
  };

  return (
    <div style={{ padding: '24px' }}>
      <Card title="Normal Route Builder" style={{ marginBottom: '24px' }}>
        <div style={{ display: 'flex', gap: '16px', marginBottom: '16px' }}>
          <Input
            placeholder="Route (e.g., BOS-NYC-MIA)"
            value={path}
            onChange={(e) => setPath(e.target.value)}
            style={{ flex: 1 }}
          />
          <RangePicker
            onChange={(dates) => setDateRange(dates)}
            style={{ width: '300px' }}
          />
        </div>
        <div style={{ display: 'flex', gap: '16px', marginBottom: '16px' }}>
          <Select
            mode="multiple"
            placeholder="Exclude sources"
            value={sourcesExcluded}
            onChange={setSourcesExcluded}
            style={{ flex: 1 }}
            options={getSourceCodenames().map(source => ({
              label: source,
              value: source
            }))}
          />
          <Input
            placeholder="Partner Authorization"
            value={apiKey}
            onChange={(e) => setApiKey(e.target.value)}
            style={{ flex: 1 }}
          />
        </div>
        <Button 
          type="primary" 
          onClick={onSearch}
          loading={isLoading}
          style={{ width: '100%', backgroundColor: '#000000' }}
        >
          Search
        </Button>
        {errors.path && <div style={{ color: 'red', marginTop: '8px' }}>{errors.path}</div>}
        {errors.general && <div style={{ color: 'red', marginTop: '8px' }}>{errors.general}</div>}
      </Card>

      {flightData && (
        <NormalFlightAvailabilityCalendar
          flightData={flightData}
          currentRoute={currentRoute}
          onDateRangeSelect={(range) => setDateRange(range)}
          selectedRange={dateRange}
        />
      )}
    </div>
  );
};

export default NormalRouteBuilder;
